var buildXML
listbuildXML = func(value,indentLevel){
    result = ""
    indent = str.Repeat("  ",indentLevel)
    switch string(type(value)){
        case "*orderedmap.OrderedMap":
            for k,v = range value{
                if (string(type(v)) == "map[string]interface {}"||string(type(v)) == "*orderedmap.OrderedMap"||string(type(v)) == "[]interface {}") && len(v) == 0{
                    result = result + indent + "<" + k + "/>\n"
                }else if string(type(v)) == "string" && len(v) == 0 {
                    result = result + indent + "<" + k + ">"
                    result = result+"</" + k + ">\n"
                }else{
                    result = result + indent + "<" + k + ">\n"
                    result = result + buildXML(v,indentLevel+1)
                    result = result + indent + "</" + k + ">\n"
                }
            }
        case "map[string]interface {}":
                        for k,v = range value{
                if (string(type(v)) == "map[string]interface {}"||string(type(v)) == "*orderedmap.OrderedMap"||string(type(v)) == "[]interface {}") && len(v) == 0{
                    result = result + indent + "<" + k + "/>\n"
                }else if string(type(v)) == "string" && len(v) == 0 {
                    result = result + indent + "<" + k + ">"
                    result = result+"</" + k + ">\n"
                }else{
                    result = result + indent + "<" + k + ">\n"
                    result = result + buildXML(v,indentLevel+1)
                    result = result + indent + "</" + k + ">\n"
                }
            }
        case "[]interface {}":
            for _,item := range value{
                result = result + listbuildXML(item,indentLevel+1)
            }
        case nil:
            result = result + indent + "<item xsi:nil=\"true\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"/>\n"
        case "[]int":
            for _,item := range value{
                result = result + listbuildXML(item,indentLevel+1)
            }
        case "[]float64":
            for _,item := range value{
                result = result + listbuildXML(item,indentLevel+1)
            }
        case "bool":
            strVal = string(value)
            result = result + indent + "<item>" + strVal + "</item>\n"
        case "float64":
            strFloat64 = string(value)
            result = result + indent + "<item>" + strFloat64 + "</item>\n"
        case "int":
            result = result + indent + "<item>" + value + "</item>\n"
        case "string":
            result = result + indent + "<item>" + value + "</item>\n"
        default:
            result = result + indent + "<item>" + str.f("%v",value) + "</item>\n"
    }
    return result
}

buildXML = func(value,indentLevel){
    result = ""
    indent = str.Repeat("  ",indentLevel) //缩进
    // println(string(type(value)) == "*orderedmap.OrderedMap")
    switch string(type(value)){
        case "*orderedmap.OrderedMap":
            for k,v = range value{
                if (string(type(v)) == "map[string]interface {}"||string(type(v)) == "*orderedmap.OrderedMap"||string(type(v)) == "[]interface {}") && len(v) == 0{
