                    result = result + buildXML(v,indentLevel+1)
                    result = result + indent + "</" + k + ">\n"
                }
            }
        case "map[string]interface {}":
                        for k,v = range value{
                if (string(type(v)) == "map[string]interface {}"||string(type(v)) == "*orderedmap.OrderedMap"||string(type(v)) == "[]interface {}") && len(v) == 0{
                    result = result + indent + "<" + k + "/>\n"
                }else if string(type(v)) == "string" && len(v) == 0 {
                    result = result + indent + "<" + k + ">"
                    result = result+"</" + k + ">\n"
                }else{
                    result = result + indent + "<" + k + ">\n"
                    result = result + buildXML(v,indentLevel+1)
                    result = result + indent + "</" + k + ">\n"
                }
            }
        case "[]interface {}":
            for _,item := range value{
                result = result + listbuildXML(item,indentLevel+1)
            }
        case nil:
            result = result + indent + "<item xsi:nil=\"true\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"/>\n"
        case "[]int":
            for _,item := range value{
                result = result + listbuildXML(item,indentLevel+1)
            }
        case "[]float64":
            for _,item := range value{
                result = result + listbuildXML(item,indentLevel+1)
            }
        case "bool":
            strVal = string(value)
            result = result + indent +strVal + "\n"
        case "float64":
            strFloat64 = string(value)
            result = result + indent + strFloat64 + "\n"
        case "int":
            result = result + indent +value + "\n"
        case "string":
            result = result + indent + value + "\n"
        default:
            result = result + indent + "<item>" + str.f("%v",value) + "</item>\n"
    }
    return result
}
JSONToXML = func(jsonstr,rootName){
    data = json.loads(jsonstr)
    if data == jsonstr{
        return data
    }
    var builder  = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
    builder = builder + "<" + rootName + ">\n"
    builder = builder + buildXML(data, 1)
    builder = builder + "</" + rootName + ">"
    return builder
}

handle = func(origin /*string*/) {
    body = poc.GetHTTPPacketBody(origin)
    xmlbody = JSONToXML(body,"request")
    origin = poc.ReplaceHTTPPacketBody(origin, xmlbody)
    return string(origin)
}
